parameters.jsCode:
const input = $input.first().json;
const BASE_URL = 'https://www.intellifoam.se/api/integrations/bot';
const API_KEY = 'intellifoam_n8n_2026';

const { action, ...params } = input;

const endpoints = {
  dashboard: { method: 'GET', path: '/dashboard' },
  search: { method: 'GET', path: '/search' },
  bookings: { method: 'GET', path: '/bookings' },
  tasks_list: { method: 'GET', path: '/tasks' },
  tasks_create: { method: 'POST', path: '/tasks' },
  tasks_update: { method: 'PUT', path: '/tasks' },
  quotes: { method: 'GET', path: '/quotes' },
  materials: { method: 'GET', path: '/materials' }
};

const endpoint = endpoints[action];
if (!endpoint) {
  return JSON.stringify({ error: 'Unknown action', validActions: Object.keys(endpoints) });
}

let url = BASE_URL + endpoint.path;

if (endpoint.method === 'GET') {
  const queryParams = [];
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== null && value !== '') {
      queryParams.push(`${key}=${encodeURIComponent(value)}`);
    }
  }
  if (queryParams.length > 0) {
    url += '?' + queryParams.join('&');
  }
}

try {
  const options = {
    method: endpoint.method,
    url: url,
    headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json' },
    json: true
  };

  if (endpoint.method !== 'GET') {
    const bodyParams = {};
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== null && value !== '') {
        bodyParams[key] = value;
      }
    }
    if (Object.keys(bodyParams).length > 0) {
      options.body = bodyParams;
    }
  }

  const response = await this.helpers.httpRequest(options);
  return JSON.stringify(response, null, 2);
} catch (error) {
  return JSON.stringify({ error: true, message: error.message, action: action, url: url });
}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": ["dashboard", "search", "bookings", "tasks_list", "tasks_create", "tasks_update", "quotes", "materials"],
      "description": "Which API action to perform"
    },
    "q": {
      "type": "string",
      "description": "Search query - customer name, phone, address, or quote number (for search action)"
    },
    "id": {
      "type": "number",
      "description": "Task ID (for tasks_update)"
    },
    "title": {
      "type": "string",
      "description": "Task title (for tasks_create)"
    },
    "description": {
      "type": "string",
      "description": "Task description (for tasks_create)"
    },
    "priority": {
      "type": "string",
      "enum": ["low", "medium", "high", "urgent"],
      "description": "Task priority (for tasks_create)"
    },
    "due_date": {
      "type": "string",
      "description": "Due date in YYYY-MM-DD format"
    },
    "status": {
      "type": "string",
      "description": "Status to set - use 'completed' to mark task as done (for tasks_update)"
    },
    "from": {
      "type": "string",
      "description": "Start date YYYY-MM-DD (for bookings)"
    },
    "to": {
      "type": "string",
      "description": "End date YYYY-MM-DD (for bookings)"
    },
    "type": {
      "type": "string",
      "description": "Filter by type - 'installation' or 'visit' (for bookings)"
    },
    "include_shipments": {
      "type": "boolean",
      "description": "Include pending shipments info (for materials)"
    }
  },
  "required": ["action"]
}
